-- SYNTHETIC, disposable PostgreSQL fixture only; never a production migration or real-data backup.
CREATE TABLE users (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(255), email varchar(255) UNIQUE, password varchar(255), role varchar(255));
CREATE TABLE categories (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(255) NOT NULL UNIQUE, description varchar(255));
CREATE TABLE products (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(255) NOT NULL, description varchar(1000), price numeric(38,2) NOT NULL, discount_price numeric(38,2), brand varchar(255), stock_quantity integer NOT NULL, skin_type varchar(255), ingredients text, status varchar(255), image_url text, images text, category_id bigint REFERENCES categories(id));
CREATE TABLE carts (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id bigint UNIQUE REFERENCES users(id), total_price double precision);
CREATE TABLE cart_items (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, cart_id bigint REFERENCES carts(id), product_id bigint REFERENCES products(id), quantity integer, price double precision);
CREATE TABLE orders (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id bigint REFERENCES users(id), customer_name varchar(255), customer_phone varchar(255), customer_email varchar(255), postal_code varchar(255), shipping_address varchar(255), payment_method varchar(255), delivery_charge double precision, payment_status varchar(255), total_amount double precision, coupon_code varchar(255), discount_amount double precision, status varchar(255), order_date timestamp(6) without time zone);
CREATE TABLE order_item (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id bigint NOT NULL REFERENCES orders(id), product_id bigint NOT NULL REFERENCES products(id), quantity integer, price double precision);
CREATE TABLE reviews (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, rating integer NOT NULL, comment varchar(1000) NOT NULL, created_at timestamp(6) without time zone, user_id bigint NOT NULL REFERENCES users(id), product_id bigint NOT NULL REFERENCES products(id));
CREATE TABLE wishlist_items (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), product_id bigint NOT NULL REFERENCES products(id), added_at timestamp(6) without time zone);
